const { app, action, core } = require("photoshop");

async function main() {
    await core.executeAsModal(async () => {

        const doc = app.activeDocument;

        // 0a. PROMOTE FROM BACKGROUND LAYER (if it is one)
        //     A Photoshop "Background" layer always reports its .bounds as
        //     the FULL CANVAS regardless of actual opaque pixel content —
        //     that's a data-model rule, not something segmentation quality
        //     affects. If removeBackground2's output is still flagged as
        //     Background, every bounds-based crop below has been padding
        //     around the entire canvas instead of the bird, which is
        //     exactly why the alpha trims correctly but the canvas never
        //     tightens. Promote to a normal layer first so .bounds means
        //     what it should. Harmless no-op (caught) if it's already a
        //     regular layer.
        try {
            await action.batchPlay(
                [ { _obj: "backgroundLayer", newName: "Layer 0" } ],
                { synchronousExecution: true }
            );
        } catch (e) { /* already a regular layer */ }

        // 0. WORK IN 16-BIT
        //    Source is an 8-bit JPEG, but every tone/color op below
        //    stacks on top of the last one. Doing that math in 8-bit
        //    compounds rounding error into banding, especially in
        //    soft bokeh gradients. Convert up now, back down to 8-bit
        //    only at the very end of the pipeline (#44).
        await action.batchPlay(
            [ { _obj: "convertMode", depth: 16 } ],
            { synchronousExecution: true }
        );

        // 0b. TRIM TO JUST THE BIRD
        //     removeBackground2 removes the true background but
        //     keeps any foreground element the subject is touching
        //     (the feeder perch, the seed/mussel pile) as part of
        //     the same opaque region, since it's physically
        //     contiguous with the bird. Every step below (crop,
        //     background blur, subject-only clarity/grade in later
        //     nodes) trusts this alpha to know what's the subject —
        //     so re-select just the bird and clear everything else
        //     before anything else runs. Same autoCutout/inverse/
        //     delete/inverse sequence the original .atn opens with.
        await action.batchPlay(
            [ { _obj: "autoCutout", sampleAllLayers: false } ],
            { synchronousExecution: true }
        );

        await action.batchPlay(
            [ { _obj: "inverse" } ],
            { synchronousExecution: true }
        );

        await action.batchPlay(
            [ { _obj: "delete" } ],
            { synchronousExecution: true }
        );

        await action.batchPlay(
            [ { _obj: "inverse" } ],
            { synchronousExecution: true }
        );

        // 0c. REDUCE THE RECURRING GLARE/GHOST RING
        //     Present in every render this whole project — a soft,
        //     low-contrast lens-flare ghost on the chest. No reliable
        //     way to locate its exact coordinates, so instead of
        //     guessing a spot to heal, Dust & Scratches (threshold-
        //     based) is applied to just the subject selection: it
        //     smooths low-contrast blemishes while leaving
        //     high-contrast edges (eye, beak, feather barbs) alone —
        //     the right tool for "faint artifact vs. real detail,"
        //     not a guaranteed full removal.
        await action.batchPlay(
            [ { _obj: "dustAndScratches", radius: 3, threshold: 10 } ],
            { synchronousExecution: true }
        );

        // ==============================================
        // BIRD BUDDY PRE-UPSCALE CORRECTION PASS
        // Fixed-lens feeder cams commonly produce:
        //  - purple/green edge fringing on cutout subjects
        //  - backlit/underexposed subjects against bright sky
        //  - green/blue color cast from canopy-filtered light
        // Corrected here, before the subject reaches the Clio
        // F16 upscale, so none of it gets baked in/amplified.
        // ==============================================

        // 1. DEFRINGE (edge fringing on the cutout alpha edge)
        await action.batchPlay(
            [ { _obj: "defringe", width: 2 } ],
            { synchronousExecution: true }
        );

        // 2. SHADOW/HIGHLIGHT RECOVERY (backlit subject detail)
        await action.batchPlay(
            [
                {
                    _obj: "shadowHighlight",
                    shadowAmount: 35,
                    shadowWidth: 50,
                    shadowRadius: 30,
                    highlightAmount: 15,
                    highlightWidth: 50,
                    highlightRadius: 30,
                    // Bumped from 1: veiling glare/lens flare (the recurring
                    // washed-out chest ring seen across every sample) reduces
                    // local contrast. Restoring more black-point contrast is
                    // the standard de-haze counter-move — reduces its
                    // visual prominence without needing to know where it
                    // lands (which we still can't detect).
                    blackClipping: 4,
                    whiteClipping: 1,
                    adjustments: {
                        _obj: "shadowHighlightCorrection",
                        colorCorrection: 20,
                        midtoneContrast: 0
                    }
                }
            ],
            { synchronousExecution: true }
        );

        // 3. WHITE BALANCE NEUTRALIZE (canopy green/blue cast)
        await action.batchPlay(
            [
                {
                    _obj: "colorBalance",
                    shadowLevels: [0, 0, 5],
                    midtoneLevels: [8, -4, -10],
                    highlightLevels: [0, 0, 0],
                    preserveLuminosity: true
                }
            ],
            { synchronousExecution: true }
        );

        // 3b. SURFACE BLUR (smooth blotchy small-sensor tonal
        //     noise while respecting edges — same visual goal as
        //     classic frequency separation, without the fragile
        //     multi-layer Apply Image math.)
        await action.batchPlay(
            [ { _obj: "surfaceBlur", radius: 6, threshold: 15 } ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 4. SUBJECT-LOCKED RECOMPOSE
        //    Feeder-cam framing leaves a lot of dead space
        //    around a small bird. Crop tighter around the
        //    detected subject (with headroom so nothing gets
        //    clipped) so every downstream upscale spends its
        //    resolution budget on the bird, not empty canvas.
        // ==============================================

        const subjectLayer = doc.layers[0];
        const b = subjectLayer.bounds;

        const subjW = b.right - b.left;
        const subjH = b.bottom - b.top;

        // The crop() call above this comment used to be a silent no-op
        // (array vs. object bug), so 0.35 padding was never actually
        // tested at real strength. Once real, it cropped down to barely
        // more than the bird's own bounding box — leaving almost no room
        // for #41's in-painting to generate a flock/background scene, and
        // forcing the same 4x (Clio 2x + Topaz 2x) upscale chain to
        // stretch a much smaller source much further, magnifying every
        // existing defect (including the ghost artifact) proportionally
        // larger. Padding bumped way up, AND floored to a fraction of the
        // ORIGINAL canvas so a small bird can never collapse the crop to
        // an unusably tiny working area regardless of padding math.
        const padX = subjW * 2.5;
        const padY = subjH * 2.5;

        let cropLeft = Math.max(0, b.left - padX);
        let cropTop = Math.max(0, b.top - padY);
        let cropRight = Math.min(doc.width, b.right + padX);
        let cropBottom = Math.min(doc.height, b.bottom + padY);

        const minW = doc.width * 0.5;
        const minH = doc.height * 0.5;
        const cx = (cropLeft + cropRight) / 2;
        const cy = (cropTop + cropBottom) / 2;

        if (cropRight - cropLeft < minW) {
            cropLeft = Math.max(0, cx - minW / 2);
            cropRight = Math.min(doc.width, cx + minW / 2);
        }
        if (cropBottom - cropTop < minH) {
            cropTop = Math.max(0, cy - minH / 2);
            cropBottom = Math.min(doc.height, cy + minH / 2);
        }

        // Document.crop() takes a Bounds OBJECT ({left, top, right,
        // bottom}), not a positional array — verified against the actual
        // UXP Photoshop class reference (AdobeDocs/uxp-photoshop). Passing
        // an array here was the real reason this crop never visibly
        // tightened; the earlier "Background layer" theory was wrong.
        await doc.crop({ left: cropLeft, top: cropTop, right: cropRight, bottom: cropBottom });

    }, {
        commandName: "FlockOfBirds - Bird Buddy Pre-Upscale Correction + Recompose"
    });
}

main();

const { app, action, core } = require("photoshop");

async function main() {
    await core.executeAsModal(async () => {

        const doc = app.activeDocument;

        // ==============================================
        // 1. AUTO TONE
        // ==============================================

        await action.batchPlay(
            [
                { _obj: "levels", auto: true }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 2. AUTO CONTRAST
        // ==============================================

        await action.batchPlay(
            [
                { _obj: "levels", auto: true, autoContrast: true }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 3. AUTO COLOR
        //    (auto black/white points + snap neutral midtones)
        // ==============================================

        await action.batchPlay(
            [
                { _obj: "levels", auto: true, autoBlackWhite: true, autoNeutrals: true }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 4. FLATTEN IMAGE
        // ==============================================

        await action.batchPlay(
            [
                { _obj: "flattenImage" }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 5. FLOCKOFBIRDS CLIO F16 UPSCALE
        // ==============================================

        await action.batchPlay(
            [
                {
                    _obj: "generativeUpscale",
                    Scl: 2,
                    serviceID: "clio_upscaler",
                    serviceVersion: "clio_f16_async",

                    modelSpecificParameters: {
                        _obj: "null",
                        face_enhancement: false,
                        creativityLevel: 0
                    },

                    output_format: "png"
                }
            ],
            {
                synchronousExecution: true
            }
        );

        // ==============================================
        // 6. Make Vibrance adjustment layer
        // ==============================================

        await action.batchPlay(
            [
                {
                    _obj: "make",
                    _target: [
                        {
                            _ref: "adjustmentLayer"
                        }
                    ],
                    using: {
                        _obj: "adjustmentLayer",
                        type: {
                            _obj: "vibrance",
                            vibrance: 50
                        }
                    }
                }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 7. Set Vibrance = +50
        // ==============================================

        await action.batchPlay(
            [
                {
                    _obj: "set",
                    _target: [
                        {
                            _ref: "adjustmentLayer",
                            _enum: "ordinal",
                            _value: "targetEnum"
                        }
                    ],
                    to: {
                        _obj: "vibrance",
                        temperature: 0,
                        tint: 0,
                        vibrance: 50,
                        useLegacy: true
                    }
                }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 8. Select All Layers
        // ==============================================

        await action.batchPlay(
            [
                { _obj: "selectAllLayers" }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 9. Auto-Blend Layers (maxDOF) — seam/tone blend
        //    of the Clio F16 upscale result before flattening.
        // ==============================================

        await action.batchPlay(
            [
                {
                    _obj: "mergeAlignedLayers",
                    Aply: {
                        _enum: "autoBlendType",
                        _value: "maxDOF"
                    },
                    ClrC: false,
                    autoTransparencyFill: false
                }
            ],
            { synchronousExecution: true }
        );

        // ==============================================
        // 10. Merge Visible
        // ==============================================

        await doc.mergeVisibleLayers();

    }, {
        commandName: "FlockOfBirds - Auto Tone/Contrast/Color + Clio F16 Upscale + Vibrance + Auto-Blend"
    });
}

main();

const { app, action, core } = require("photoshop");

async function main() {
    await core.executeAsModal(async () => {

        // Main document = #29 auto-toned/contrast/color-corrected,
        // Clio F16-upscaled subject canvas.
        const baseDoc = app.activeDocument;

        // Additional Content #1 = #5 protected subject PSD
        // (pre-upscale, pixel-perfect original subject).
        const subjectDoc = app.documents.find(
            d => d.id !== baseDoc.id
        );

        if (!subjectDoc) {
            throw new Error("Protected subject document (#5) was not loaded.");
        }

        // ---------------------------------------------------------
        // 1. MATCH SUBJECT DOCUMENT TO #29 UPSCALED CANVAS
        // ---------------------------------------------------------

        const targetWidth = baseDoc.width;
        const targetHeight = baseDoc.height;
        const targetResolution = baseDoc.resolution;

        app.activeDocument = subjectDoc;

        await subjectDoc.resizeImage(
            targetWidth,
            targetHeight,
            targetResolution
        );

        // ---------------------------------------------------------
        // 2. COPY THE TRANSPARENT SUBJECT
        // ---------------------------------------------------------

        await action.batchPlay(
            [
                {
                    _obj: "set",
                    _target: [
                        {
                            _ref: "channel",
                            _property: "selection"
                        }
                    ],
                    to: {
                        _ref: "channel",
                        _enum: "channel",
                        _value: "transparencyEnum"
                    }
                }
            ],
            {
                synchronousExecution: true
            }
        );

        await action.batchPlay(
            [
                {
                    _obj: "copyEvent",
                    copyHint: "pixels"
                }
            ],
            {
                synchronousExecution: true
            }
        );

        // ---------------------------------------------------------
        // 3. RETURN TO THE UPSCALED CANVAS
        // ---------------------------------------------------------

        app.activeDocument = baseDoc;

        // ---------------------------------------------------------
        // 4. PASTE ORIGINAL SUBJECT IN EXACT REGISTER
        //    (undoes any softening/drift the Clio F16 upscale,
        //    vibrance, and Auto-Blend Layers pass introduced,
        //    so the subject autoCutout mask used for generative
        //    fill in the next step is pixel-perfect.)
        // ---------------------------------------------------------

        await action.batchPlay(
            [
                {
                    _obj: "paste",
                    antiAlias: {
                        _enum: "antiAliasType",
                        _value: "antiAliasNone"
                    },
                    as: {
                        _class: "pixel"
                    }
                }
            ],
            {
                synchronousExecution: true
            }
        );

        const subjectLayer = baseDoc.activeLayers[0];

        if (subjectLayer) {
            subjectLayer.name = "PROTECTED ORIGINAL SUBJECT (PRE-FILL)";
        }

        // ---------------------------------------------------------
        // 5. MERGE THE RESTORED SUBJECT INTO THE UPSCALED CANVAS
        // ---------------------------------------------------------

        await baseDoc.mergeVisibleLayers();

        app.activeDocument = baseDoc;

    }, {
        commandName: "FlockOfBirds - Restore Protected Subject (Pre-Fill)"
    });
}

main();

const { app, action, core } = require("photoshop");

async function main() {

    await core.executeAsModal(async () => {

        // ==============================================
        // 1. SELECT SUBJECT
        // ==============================================

        await action.batchPlay([
            {
                _obj: "autoCutout",
                sampleAllLayers: false
            }
        ], {
            synchronousExecution: true
        });


        // ==============================================
        // 2. INVERT SELECTION
        //    Subject protected; background selected.
        // ==============================================

        await action.batchPlay([
            {
                _obj: "inverse"
            }
        ], {
            synchronousExecution: true
        });


        // ==============================================
        // 3. FLOCKOFBIRDS CLIO3 GENERATIVE FILL
        //    Prompt tightened to request matching species/scale — the
        //    generic "flock of birds" was producing large wading birds
        //    (herons/ibis-scale) alongside a small perching songbird
        //    subject, an obvious species/scale mismatch that undercut
        //    believability regardless of technical post quality. This
        //    text-only change is independent of the selection mechanism
        //    above (reverted to the original autoCutout after the
        //    mask-reconstruction rewrite broke the fill entirely — that
        //    baseDoc is fully flattened/opaque by this point, no alpha
        //    left to reconstruct a selection from).
        // ==============================================

        await action.batchPlay([
            {
                _obj: "syntheticFill",

                _target: [
                    {
                        _ref: "document",
                        _enum: "ordinal",
                        _value: "targetEnum"
                    }
                ],

                prompt: "flock of small songbirds, same species and scale as the perched bird in the foreground",

                serviceID: "clio",

                workflowType: {
                    _enum: "genWorkflow",
                    _value: "in_painting"
                },

                serviceOptionsList: {
                    _obj: "null",

                    clio: {
                        _obj: "clio",

                        gi_PROMPT: "flock of small songbirds, same species and scale as the perched bird in the foreground",
                        gi_MODE: "ginp",
                        gi_SEED: -1,
                        gi_NUM_STEPS: -1,
                        gi_GUIDANCE: 6,
                        gi_SIMILARITY: 0,
                        gi_CROP: false,
                        gi_DILATE: false,
                        gi_CONTENT_PRESERVE: 0,
                        gi_ENABLE_PROMPT_FILTER: true,

                        dualCrop: true,

                        gentech_workflow_name: "in_painting",

                        gen_use_object_stitch: false
                    }
                },

                serviceVersion: "clio3"
            }
        ], {
            synchronousExecution: true
        });


        // ==============================================
        // 4. DESELECT
        // ==============================================

        await app.activeDocument.selection.deselect();

    }, {
        commandName: "FlockOfBirds - CLIO3 Generative Fill"
    });
}

main();

