main();

const { app, action, core } = require("photoshop");

async function main() {
    await core.executeAsModal(async () => {

        // =========================================================
        // 0. REDUCE NOISE
        //    Sensor/JPEG noise gets amplified by the 2x Topaz
        //    upscale below; knock it down first so the upscaler
        //    isn't sharpening noise into fake detail.
        // =========================================================

        await action.batchPlay(
            [
                {
                    _obj: "reduceNoise",
                    strength: 6,
                    preserveDetails: 40,
                    reduceColorNoise: 25,
                    sharpenDetails: 0,
                    removeJPEGArtifact: true
                }
            ],
            { synchronousExecution: true }
        );

        // =========================================================
        // 1. TOPAZ STANDARD V2 — 2x
        // =========================================================

        await action.batchPlay(
            [
                {
                    _obj: "generativeUpscale",

                    Scl: 2,

                    serviceID: "gateway_service",

                    serviceVersion:
                        "gateway_topaz_standard_v2",

                    modelSpecificParameters: {
                        _obj: "null",
                        face_enhancement: false,
                        creativityLevel: 0
                    },

                    output_format: "png"
                }
            ],
            {
                synchronousExecution: true
            }
        );

        // Topaz creates a NEW document.
        const upscaledDoc = app.activeDocument;

        // =========================================================
        // 2. MERGE VISIBLE
        // =========================================================

        await upscaledDoc.mergeVisibleLayers();

        // =========================================================
        // 3. IMAGE SIZE
        // 7680 px (8K UHD width) / 300 ppi — print + all-media ready
        // =========================================================

        await upscaledDoc.resizeImage(
            7680,
            undefined,
            300
        );

        // Leave the Topaz result document active.
        app.activeDocument = upscaledDoc;

    }, {
        commandName: "FlockOfBirds - Topaz Standard v2 2x"
    });
}

main();

const { app, action, core } = require("photoshop");

async function main() {
    await core.executeAsModal(async () => {

        // Main document = #35 final generated/upscaled scene.
        const baseDoc = app.activeDocument;

        // Additional Content #1 = #5 protected subject PSD.
        // With one additional content, it should be the other open doc.
        const subjectDoc = app.documents.find(
            d => d.id !== baseDoc.id
        );

        if (!subjectDoc) {
            throw new Error("Protected subject document (#5) was not loaded.");
        }

        // ---------------------------------------------------------
        // 1. MATCH SUBJECT DOCUMENT TO FINAL #35 CANVAS
        // ---------------------------------------------------------

        const targetWidth = baseDoc.width;
        const targetHeight = baseDoc.height;
        const targetResolution = baseDoc.resolution;

        app.activeDocument = subjectDoc;

        await subjectDoc.resizeImage(
            targetWidth,
            targetHeight,
            targetResolution
        );

        // ---------------------------------------------------------
        // 2. COPY THE TRANSPARENT SUBJECT
        // ---------------------------------------------------------

        // Select visible subject pixels by selecting transparency.
        await action.batchPlay(
            [
                {
                    _obj: "set",
                    _target: [
                        {
                            _ref: "channel",
                            _property: "selection"
                        }
                    ],
                    to: {
                        _ref: "channel",
                        _enum: "channel",
                        _value: "transparencyEnum"
                    }
                }
            ],
            {
                synchronousExecution: true
            }
        );

        await action.batchPlay(
            [
                {
                    _obj: "copyEvent",
                    copyHint: "pixels"
                }
            ],
            {
                synchronousExecution: true
            }
        );

        // ---------------------------------------------------------
        // 3. RETURN TO GENERATED SCENE
        // ---------------------------------------------------------

        app.activeDocument = baseDoc;

        // ---------------------------------------------------------
        // 4. PASTE ORIGINAL SUBJECT IN EXACT REGISTER
        // ---------------------------------------------------------

        await action.batchPlay(
            [
                {
                    _obj: "paste",
                    antiAlias: {
                        _enum: "antiAliasType",
                        _value: "antiAliasNone"
                    },
                    as: {
                        _class: "pixel"
                    }
                }
            ],
            {
                synchronousExecution: true
            }
        );

        const subjectLayer = baseDoc.activeLayers[0];

        if (subjectLayer) {
            subjectLayer.name = "PROTECTED ORIGINAL SUBJECT";
        }

        // ---------------------------------------------------------
        // 5. MERGE THE RESTORED SUBJECT INTO FINAL SCENE
        // ---------------------------------------------------------

        await baseDoc.mergeVisibleLayers();

        app.activeDocument = baseDoc;

    }, {
        commandName: "FlockOfBirds - Restore Protected Original Subject"
    });
}

main();

const { app, action, core } = require("photoshop");

async function main() {
    await core.executeAsModal(async () => {

        const baseDoc = app.activeDocument;

        // Additional Content #1 = #46 corrected subject PSD, reused
        // purely to borrow its alpha as a subject/background mask
        // (same select-transparency/copy/paste technique already
        // proven in #43/#42/#47).
        const subjectDoc = app.documents.find(
            d => d.id !== baseDoc.id
        );

        if (!subjectDoc) {
            throw new Error("Corrected subject document (#46) was not loaded.");
        }

        // =========================================================
        // 0. LOAD THE SUBJECT SILHOUETTE AS A SELECTION
        // =========================================================

        app.activeDocument = subjectDoc;

        await subjectDoc.resizeImage(
            baseDoc.width,
            baseDoc.height,
            baseDoc.resolution
        );

        await action.batchPlay(
            [
                {
                    _obj: "set",
                    _target: [ { _ref: "channel", _property: "selection" } ],
                    to: { _ref: "channel", _enum: "channel", _value: "transparencyEnum" }
                }
            ],
